summary={'status':'ACCEPTED four centered same-width 5V_BUCK donor replacements with finite annular contacts; native DRC remains unfinished','source_directory':str(S),'source_board_sha256':sha(SP),'candidate_board_sha256':sha(P),'schematic_sha256':sha(O/'hardware/nexus-style-fc.kicad_sch'),'native_drc_sha256':sha(O/'native-drc.json'),'source_clearance_errors':len(ea),'candidate_clearance_errors':len(eb),'unchanged_silk_warnings':sum(wb.values()),'opens':0,'schematic_parity_issues':0,'erc_violations':0,'erc_evidence_basis':'Exact unchanged schematic and source-native ERC receipt; fresh PCB schematic-parity check','minimum_remaining_clearance_mm':min(eb.values()),'worsened_residual_pairs':worse,'removed_native_violation_pairs':list((ca-cb).elements()),'new_native_violation_pairs':[],'geometry_receipt_sha256':sha(O/'geometry-verification.json'),'invariants':g['invariants']['status'],'remaining_inherited_pasted_vias':g['pasted_vias_unchanged'],'all_visible_centering_findings_before':17,'all_visible_centering_findings_after':13,'all_visible_filter_warnings':0,'all_visible_footprint_type_warnings':5,'complete_port_proofs':g['route_physical_proofs'],'power_reference_measurements':thermal['power_projection_changes'],'non_port_reference_measurements':nonport['non_port_changes'],'reference_basis':nonport['regions_basis'],'untouched_direct_contacts_preserved':g['untouched_original_direct_contacts_preserved'],'all_changed_original_direct_contacts_preserved':True,'shield_regions_preserved':96,'retained_power_roles':'R11 feedback divider, U9 VIN1 downstream load transfer, and U5 VOS sense branch. The inherited VOS tap upstream of C24 remains an explicit device-layout qualification gate.','main_In1_In4_ground_fill_exact':True,'en_conductive_contacts':g['en_conductive_contacts'],'qualification':'Native unfinished routing checkpoint only. Whole-annulus geometry does not establish via ampacity or thermal rating. Inherited U5 VOS sense topology, power/transient/return, regulator capacitor loops, USB/SI, 16 pasted-via locations, header/mechanical and fabrication gates remain open.'};(O/'verification.json').write_text(json.dumps(summary,indent=2)+'\n')
